# Inert endpoint stages of SIM-MP-026 (see the scenario for the full per-step commands).
$lab = 'C:\ProgramData\cortexsim-mp026'
New-Item -ItemType Directory -Force -Path "$lab\assembly", "$lab\tools", "$lab\stage" | Out-Null
Copy-Item (Join-Path $env:WINDIR 'Microsoft.NET\Framework64\v4.0.30319\mscorsvw.exe') "$lab\assembly\mscorsvw.exe" -Force
Set-Content "$lab\assembly\mscorsvc.dll" 'cortexsim-mp026 inert side-load stand-in, not a PE'
if (-not (Get-Service msdnetsvc -ErrorAction SilentlyContinue)) { sc.exe create msdnetsvc binPath= "$lab\assembly\mscorsvw.exe" start= demand }
$stage = if ($env:STAGE_HOST) { $env:STAGE_HOST } else { '127.0.0.1' }
try { Invoke-WebRequest -UseBasicParsing -TimeoutSec 5 -Uri "http://${stage}:8080/" | Out-Null } catch { }
